<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api'
import SalesOrderPrint from '../components/SalesOrderPrint.vue'

const rows=ref<any[]>([]),loading=ref(false),editor=ref(false),detail=ref<any>(null),resolving=ref(false),availableOrders=ref<any[]>([]),orderSearching=ref(false),orderTail=ref('')
const orderTailInput=ref<any>(null)
const newDraft=ref(false),draftDirty=ref(false)
const inlineDispatch=ref<any>(null),inlineDispatchLoading=ref(false),selectedDispatchId=ref<number|null>(null)
const salesDetailDialog=ref(false),salesDetailLoading=ref(false),salesDetail=ref<any>(null)
const dispatchPrintDialog=ref(false)
const headerDialog=ref(false),headerSaving=ref(false),referenceDialog=ref(false),referenceSaving=ref(false),referenceType=ref<'route'|'vehicle'|'employee'>('route')
const routes=ref<any[]>([]),vehicles=ref<any[]>([]),employees=ref<any[]>([])
import { localToday } from '../utils/date'
const today=localToday()
const query=reactive({keyword:'',status:'',dateFrom:today,dateTo:today,recorder:'',sortBy:'date',sortDirection:'asc',page:1,pageSize:100})
const headerForm=reactive({dispatchDate:'',routeId:null as number|null,vehicleId:null as number|null,driverId:null as number|null,deliveryPersonId:null as number|null,remark:'',version:0})
const referenceForm=reactive({code:'',name:'',plateNo:'',phone:''})
const totalAmount=computed(()=>detail.value?.orders?.reduce((sum:number,item:any)=>sum+Number(item.amount||0),0)||0)
const drivers=computed(()=>employees.value.filter((item:any)=>`${item.typeName||''} ${item.positionName||''}`.includes('Driver')))
const referenceTitle=computed(()=>referenceType.value==='route'?'Add Route':referenceType.value==='vehicle'?'Add Vehicle':'Add Employee')
function vehicleLabel(item:any){const code=String(item.code||'').trim(),plate=String(item.plateNo||'').trim();return !plate||plate.toLowerCase()===code.toLowerCase()?code:`${code} · ${plate}`}
function employeeLabel(item:any){const code=String(item.code||'').trim(),name=String(item.name||'').trim();const clean=name.endsWith(code)?name.slice(0,-code.length).trim():name;return clean?`${code} ${clean}`:code}
function formatDateTime(value:any){return value?String(value).replace('T',' ').slice(0,19):'—'}
async function focusOrderEntry(){await nextTick();orderTailInput.value?.focus()}

async function load(){loading.value=true;try{const{data}=await api.get('/dispatch-sheets',{params:query});rows.value=data.data.items}finally{loading.value=false}}
function handleSortChange({prop,order}:{prop:string,order:string}){query.sortBy=prop==='dispatchNo'?'documentNo':'date';query.sortDirection=order==='descending'?'desc':'asc';query.page=1;load()}
async function focusNewDispatch(dispatchNo:string){await nextTick();const row=Array.from(document.querySelectorAll('.el-table__body-wrapper tbody tr')).find(x=>x.textContent?.includes(dispatchNo));if(!row)return;row.classList.add('newly-created-row');row.scrollIntoView({behavior:'smooth',block:'center'});window.setTimeout(()=>row.classList.remove('newly-created-row'),5000)}
function resetQuery(){Object.assign(query,{keyword:'',status:'',dateFrom:'',dateTo:'',recorder:'',sortBy:'date',sortDirection:'asc',page:1});load()}
async function loadOptions(){const [r,v,e]=await Promise.all([api.get('/routes'),api.get('/vehicles'),api.get('/reference-data/employees',{params:{enabled:true,page:1,pageSize:100}})]);routes.value=r.data.data;vehicles.value=v.data.data;employees.value=e.data.data.items}
function resetHeader(){Object.assign(headerForm,{dispatchDate:localToday(),routeId:null,vehicleId:null,driverId:null,deliveryPersonId:null,remark:'',version:0})}
async function openNew(){resetHeader();await loadOptions();detail.value={id:null,dispatchNo:'Create',dispatchDate:headerForm.dispatchDate,routeId:null,routeName:'',vehicleId:null,vehicleCode:'',driverId:null,driverName:'',deliveryPersonId:null,deliveryPersonName:'',status:'DRAFT',remark:'',version:0,orders:[],createdByName:'',createdAt:null,updatedByName:'',updatedAt:null,approvedByName:'',approvedAt:null,printedByName:'',printedAt:null,printCount:0};newDraft.value=true;draftDirty.value=false;availableOrders.value=[];orderTail.value='';editor.value=true;await nextTick();orderTailInput.value?.focus()}
async function ensureDraft(){if(detail.value?.id)return;const{data}=await api.post('/dispatch-sheets',headerForm);detail.value=data.data;syncHeaderForm();newDraft.value=true;draftDirty.value=true;await load();await focusNewDispatch(data.data.dispatchNo)}
async function openHeaderEdit(){await loadOptions();Object.assign(headerForm,{dispatchDate:detail.value.dispatchDate,routeId:detail.value.routeId,vehicleId:detail.value.vehicleId,driverId:detail.value.driverId,deliveryPersonId:detail.value.deliveryPersonId,remark:detail.value.remark,version:detail.value.version});headerDialog.value=true}
async function saveHeader(showMessage=true){if(!headerForm.dispatchDate)return ElMessage.warning('Select a date');headerSaving.value=true;try{if(!detail.value.id){await ensureDraft()}else{await api.put(`/dispatch-sheets/${detail.value.id}`,headerForm);await refreshDetail()}headerDialog.value=false;newDraft.value=false;draftDirty.value=false;if(showMessage)ElMessage.success('Dispatch SheetDraftSaved')}finally{headerSaving.value=false}}
function syncHeaderForm(){if(!detail.value)return;Object.assign(headerForm,{dispatchDate:detail.value.dispatchDate,routeId:detail.value.routeId,vehicleId:detail.value.vehicleId,driverId:detail.value.driverId,deliveryPersonId:detail.value.deliveryPersonId,remark:detail.value.remark||'',version:detail.value.version})}
async function openDetail(row:any){const[{data}]=await Promise.all([api.get(`/dispatch-sheets/${row.id}`),loadOptions()]);detail.value=data.data;syncHeaderForm();newDraft.value=false;draftDirty.value=false;editor.value=true;availableOrders.value=[];orderTail.value=''}
async function selectDispatch(row:any){selectedDispatchId.value=row.id;inlineDispatchLoading.value=true;try{const{data}=await api.get(`/dispatch-sheets/${row.id}`);if(selectedDispatchId.value===row.id)inlineDispatch.value=data.data}finally{if(selectedDispatchId.value===row.id)inlineDispatchLoading.value=false}}
async function openInlineDispatchDetail(){if(inlineDispatch.value)await openDetail({id:inlineDispatch.value.id})}
async function approveFromList(row:any){
  if(row.status!=='DRAFT')return
  if(!row.dispatchDate)return ElMessage.warning('Date is required before approval')
  await ElMessageBox.confirm(`Approve dispatch sheet ${row.dispatchNo}? It cannot be edited after approval.`,'Approval Confirmation',{type:'warning'})
  await api.post(`/dispatch-sheets/${row.id}/approve`,{version:row.version})
  await load()
  if(selectedDispatchId.value===row.id)await selectDispatch(row)
  ElMessage.success('Dispatch sheet approved successfully')
}
async function refreshDetail(preserveHeader=false){const{data}=await api.get(`/dispatch-sheets/${detail.value.id}`);detail.value=data.data;if(preserveHeader)headerForm.version=detail.value.version;else syncHeaderForm();await load()}
function errorMessage(error:any){
  const body=error.response?.data
  const message=body?.message||body?.detail||body?.data?.message||body?.data?.detail||body?.error
  if(message)return message
  if(!error.response)return 'Unable to connect to the server. Check whether the service is running.'
  return 'Action could not be completed. Refresh and try again.'
}
async function addResolvedOrder(orderNo:string){resolving.value=true;try{await ensureDraft();await api.post(`/dispatch-sheets/${detail.value.id}/orders`,{orderNo});await refreshDetail(true);draftDirty.value=true;availableOrders.value=[];orderTail.value='';await nextTick();orderTailInput.value?.focus();ElMessage.success(`Sales Order ${orderNo} Added to Dispatch Sheet`)}catch(error:any){ElMessage.error(errorMessage(error))}finally{resolving.value=false}}
function numericTail(orderNo:string){const match=String(orderNo||'').match(/(\d+)$/);return match?String(Number(match[1])):''}
async function resolveOrderTail(){const tail=orderTail.value.trim();if(tail&&!/^\d+$/.test(tail))return ElMessage.warning('Enter the ending digits of a sales order, such as 3, 03, or 003');orderSearching.value=true;try{await ensureDraft();let matches:any[]=[];if(tail){try{const{data}=await api.get(`/dispatch-sheets/${detail.value.id}/order-tail-candidates`,{params:{tail}});matches=data.data}catch{}if(!matches.length){const{data}=await api.get(`/dispatch-sheets/${detail.value.id}/available-orders`);const normalized=String(Number(tail));matches=data.data.filter((item:any)=>numericTail(item.orderNo)===normalized)}}else{const{data}=await api.get(`/dispatch-sheets/${detail.value.id}/available-orders`);matches=data.data}availableOrders.value=matches;if(tail&&matches.length===1)return await addResolvedOrder(matches[0].orderNo);if(matches.length===0)return ElMessage.warning(tail?`No available sales order ends in ${tail}. Confirm that the order has been printed and is not assigned to another dispatch sheet.`:'No printed sales orders are available');if(tail)ElMessage.info(`Found ${matches.length} sales orders. Select the correct document.`)}catch(error:any){ElMessage.error(errorMessage(error))}finally{orderSearching.value=false}}
function markDraftDirty(){draftDirty.value=true}
async function discardNewDraft(){if(detail.value?.id)await api.delete(`/dispatch-sheets/${detail.value.id}/draft`);detail.value=null;newDraft.value=false;draftDirty.value=false;editor.value=false;await load()}
function finishClose(done?:()=>void){detail.value=null;editor.value=false;if(done)done()}
async function closeEditor(done?:()=>void){if(detail.value?.status!=='DRAFT'){finishClose(done);return}if(newDraft.value&&!draftDirty.value){finishClose(done);return}if(newDraft.value){try{await ElMessageBox.confirm('Save changes to the current dispatch sheet?','Save Record',{confirmButtonText:'Save',cancelButtonText:'Do Not Save',distinguishCancelAndClose:true,type:'warning'});await saveHeader(false);finishClose(done)}catch(action:any){if(action==='cancel'){try{await discardNewDraft();if(done)done()}catch(error:any){ElMessage.error(errorMessage(error))}}return}return}if(draftDirty.value){syncHeaderForm();draftDirty.value=false}finishClose(done)}
async function removeOrder(row:any){try{await api.delete(`/dispatch-sheets/${detail.value.id}/orders/${row.linkId}`);await refreshDetail(true);draftDirty.value=true;ElMessage.success('Sales order removed; enter ending digits to add again')}catch(error:any){ElMessage.error(errorMessage(error))}}
async function openSalesDetail(row:any){salesDetailLoading.value=true;salesDetailDialog.value=true;try{const{data}=await api.get(`/sales-orders/${row.salesOrderId}`);salesDetail.value=data.data}finally{salesDetailLoading.value=false}}
async function printRelated(){await nextTick();window.print()}
function openDispatchPrint(){dispatchPrintDialog.value=true}
async function printDispatchSheet(){if(detail.value?.status!=='APPROVED')return ElMessage.warning('Have a supervisor approve the dispatch sheet before printing.');window.print();try{await ElMessageBox.confirm('Was the dispatch sheet printed successfully or saved as a PDF?','Confirm Dispatch Sheet Print Result',{type:'warning',confirmButtonText:'Print Successful',cancelButtonText:'Print Failed or Cancelled'});const{data}=await api.post(`/dispatch-sheets/${detail.value.id}/confirm-print`,{version:detail.value.version});ElMessage.success(data.data.firstPrint?'Dispatch sheet marked as printed':'Dispatch sheet reprint count updated');await refreshDetail();dispatchPrintDialog.value=true}catch(e:any){if(e==='cancel'||e==='close')return;ElMessage.error(errorMessage(e))}}
function csvCell(value:any){return `"${String(value??'').replaceAll('"','""')}"`}
function exportDispatch(){if(!detail.value)return;const lines=[['No.','Document Type','Order Date','Sales Order No.','Customer Code','Customer Name','Salesperson','Payment Method','Amount','Notes'],...detail.value.orders.map((x:any)=>[x.sequenceNo,'Delivery Note',x.orderDate,x.orderNo,x.customerCode,x.customerName,x.salespersonName,x.settlementMethod,x.amount,x.remark||''])];const blob=new Blob(['\ufeff'+lines.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${detail.value.dispatchNo}-Dispatch Sheet.csv`;a.click();URL.revokeObjectURL(url)}
async function approve(){if(!detail.value?.id)return ElMessage.warning('Save the dispatch sheet before approving it.');if(draftDirty.value)await saveHeader(false);if(!detail.value.dispatchDate)return ElMessage.warning('Date is required before approval');await ElMessageBox.confirm(`Approve dispatch sheet ${detail.value.dispatchNo}? It cannot be edited after approval.`,'Approval Confirmation',{type:'warning'});await api.post(`/dispatch-sheets/${detail.value.id}/approve`,{version:detail.value.version});await refreshDetail();ElMessage.success('Dispatch sheet approved successfully')}
async function voidSheet(row:any){const target=detail.value?.id===row.id?detail.value:row;if(target.status!=='DRAFT')return ElMessage.warning('Approved dispatch sheet cannot be changed');const{value}=await ElMessageBox.prompt('Enter a void reason','Void Dispatch Sheet',{inputValidator:v=>!!v||'Reason is required',type:'warning'});await api.post(`/dispatch-sheets/${target.id}/void`,{version:target.version,reason:value});if(detail.value?.id===target.id)await refreshDetail();await load();ElMessage.success('Dispatch sheet voided')}
function openReference(type:'route'|'vehicle'|'employee'){referenceType.value=type;Object.assign(referenceForm,{code:'',name:'',plateNo:'',phone:''});referenceDialog.value=true}
async function saveReference(){if(!referenceForm.code.trim())return ElMessage.warning('Enter a code');if(referenceType.value!=='vehicle'&&!referenceForm.name.trim())return ElMessage.warning('Enter Name');referenceSaving.value=true;try{const path=referenceType.value==='route'?'/routes':referenceType.value==='vehicle'?'/vehicles':'/employees';const{data}=await api.post(path,referenceForm);await loadOptions();if(referenceType.value==='route')headerForm.routeId=data.data.id;else if(referenceType.value==='vehicle')headerForm.vehicleId=data.data.id;else headerForm.driverId=data.data.id;referenceDialog.value=false;ElMessage.success(`${referenceTitle.value} successful`)}finally{referenceSaving.value=false}}
function statusText(status:string){return({DRAFT:'Draft',APPROVED:'Approved',VOIDED:'Voided',COMPLETED:'Historically Completed',REVERSED:'Historically Reversed'} as any)[status]||status}
onMounted(load)
</script>

<template>
  <section>
    <div class="page-heading"><div><h1>Dispatch Sheet</h1><p>Add printed delivery orders to a dispatch sheet for supervisor approval</p></div><el-button type="primary" @click="openNew">Create Dispatch Sheet</el-button></div>
    <el-card class="dispatch-split-card"><div class="dispatch-search"><div class="dispatch-search-row"><el-date-picker v-model="query.dateFrom" type="date" value-format="YYYY-MM-DD" placeholder="Start Date"/><span>to</span><el-date-picker v-model="query.dateTo" type="date" value-format="YYYY-MM-DD" placeholder="End Date"/><el-input v-model="query.keyword" clearable placeholder="Dispatch Sheet No. / Route / Vehicle / Driver / Delivery Person" @keyup.enter="load"/><el-input v-model="query.recorder" clearable placeholder="Created By" @keyup.enter="load"/><el-button type="primary" @click="load">Search</el-button><el-button @click="resetQuery">Clear Filters</el-button></div><el-radio-group v-model="query.status" @change="load"><el-radio-button value="">All</el-radio-button><el-radio-button value="DRAFT">Draft</el-radio-button><el-radio-button value="APPROVED">Approved</el-radio-button><el-radio-button value="VOIDED">Voided</el-radio-button></el-radio-group></div>
      <el-table :data="rows" v-loading="loading" height="42vh" stripe highlight-current-row :default-sort="{prop:'dispatchDate',order:'ascending'}" @sort-change="handleSortChange" @row-click="selectDispatch" @row-dblclick="openDetail"><el-table-column prop="dispatchNo" label="Dispatch Sheet No." width="155" sortable="custom" :sort-orders="['ascending','descending']"/><el-table-column prop="dispatchDate" label="Date" width="115" sortable="custom" :sort-orders="['ascending','descending']"/><el-table-column prop="routeName" label="Route"/><el-table-column prop="vehicleCode" label="Vehicle"/><el-table-column prop="driverName" label="Driver"/><el-table-column prop="deliveryPersonName" label="Delivery Person"/><el-table-column prop="orderCount" label="Documents" width="85"/><el-table-column prop="totalAmount" label="Total Amount" width="120"/><el-table-column label="Status" width="110"><template #default="scope"><el-tag :type="scope.row.status==='APPROVED'?'success':scope.row.status==='COMPLETED'?'primary':scope.row.status==='REVERSED'?'warning':scope.row.status==='VOIDED'?'danger':'info'">{{statusText(scope.row.status)}}</el-tag></template></el-table-column><el-table-column label="Print Status" width="120"><template #default="scope"><el-tag :type="scope.row.printedAt?'warning':'info'">{{scope.row.printedAt?`Printed × ${scope.row.printCount||1}`:'Not Printed'}}</el-tag></template></el-table-column><el-table-column label="Actions" width="205" fixed="right"><template #default="scope"><el-button link type="primary" @click.stop="openDetail(scope.row)">Details</el-button><el-button v-if="scope.row.status==='DRAFT'" link type="success" @click.stop="approveFromList(scope.row)">Approve</el-button><el-button v-if="scope.row.status==='DRAFT'" link type="danger" @click.stop="voidSheet(scope.row)">Void</el-button></template></el-table-column></el-table>
      <div class="inline-detail-panel" v-loading="inlineDispatchLoading"><div class="inline-detail-heading"><div><strong>{{inlineDispatch?`Dispatch Sheet ${inlineDispatch.dispatchNo}  sales orders`:'Click a dispatch sheet above to view sales orders'}}</strong><span v-if="inlineDispatch">Details scroll independently; double-click a sales order to open the full dispatch sheet</span></div><span v-if="inlineDispatch">Total  {{inlineDispatch.orders?.length||0}} orders, Total ¥{{Number(inlineDispatch.totalAmount||0).toFixed(2)}}</span></div><el-table v-if="inlineDispatch" :data="inlineDispatch.orders" border highlight-current-row height="190" @row-dblclick="openInlineDispatchDetail"><el-table-column prop="sequenceNo" label="No." width="65"/><el-table-column prop="orderNo" label="Sales Order No." width="150"/><el-table-column prop="orderDate" label="Order Date" width="110"/><el-table-column prop="customerCode" label="Customer Code" width="105"/><el-table-column prop="customerName" label="Customer Name" min-width="190"/><el-table-column prop="salespersonName" label="Salesperson" width="100"/><el-table-column prop="settlementMethod" label="Payment Method" width="100"/><el-table-column prop="amount" label="Amount" width="110"/></el-table><el-empty v-else :image-size="54" description="Please select a dispatch sheet"/></div>
    </el-card>

    <el-dialog v-model="headerDialog" title="Edit Dispatch Sheet Header" width="720px">
      <el-form label-width="90px"><el-form-item label="Date" required><el-date-picker v-model="headerForm.dispatchDate" type="date" value-format="YYYY-MM-DD" :clearable="false"/></el-form-item>
        <el-form-item label="Route"><div class="reference-row"><el-select v-model="headerForm.routeId" filterable clearable placeholder="Optional"><el-option v-for="item in routes" :key="item.id" :label="`${item.code} ${item.name}`" :value="item.id"/></el-select><el-button @click="openReference('route')">Add Route</el-button></div></el-form-item>
        <el-form-item label="Vehicle"><div class="reference-row"><el-select v-model="headerForm.vehicleId" filterable clearable placeholder="Optional"><el-option v-for="item in vehicles" :key="item.id" :label="vehicleLabel(item)" :value="item.id"/></el-select><el-button @click="openReference('vehicle')">Add Vehicle</el-button></div></el-form-item>
        <el-form-item label="Driver"><div class="reference-row"><el-select v-model="headerForm.driverId" filterable clearable placeholder="Optional"><el-option v-for="item in drivers" :key="item.id" :label="employeeLabel(item)" :value="item.id"/></el-select><el-button @click="openReference('employee')">Add Employee</el-button></div></el-form-item>
        <el-form-item label="Delivery Person"><el-select v-model="headerForm.deliveryPersonId" filterable clearable placeholder="Optional"><el-option v-for="item in employees" :key="item.id" :label="employeeLabel(item)" :value="item.id"/></el-select></el-form-item><el-form-item label="Notes"><el-input v-model="headerForm.remark" type="textarea"/></el-form-item></el-form>
      <template #footer><el-button @click="headerDialog=false">Cancel</el-button><el-button type="primary" :loading="headerSaving" @click="saveHeader">Save</el-button></template>
    </el-dialog>

    <el-dialog v-model="referenceDialog" :title="referenceTitle" width="500px" append-to-body><el-form label-width="90px"><el-form-item label="Code" required><el-input v-model="referenceForm.code"/></el-form-item><el-form-item v-if="referenceType!=='vehicle'" label="Name" required><el-input v-model="referenceForm.name"/></el-form-item><el-form-item v-if="referenceType==='vehicle'" label="License Plate"><el-input v-model="referenceForm.plateNo"/></el-form-item><el-form-item v-if="referenceType==='employee'" label="Phone"><el-input v-model="referenceForm.phone"/></el-form-item></el-form><template #footer><el-button @click="referenceDialog=false">Cancel</el-button><el-button type="primary" :loading="referenceSaving" @click="saveReference">Save</el-button></template></el-dialog>

    <el-dialog v-model="editor" width="1180px" top="3vh" :show-close="true" :before-close="closeEditor" class="dispatch-document-dialog">
      <template #header>
        <div class="document-toolbar">
          <el-button :disabled="!detail?.id" @click="openDispatchPrint">Print Preview</el-button>
          <el-button v-if="detail?.status==='DRAFT'" type="primary" :loading="headerSaving" @click="saveHeader()">Save</el-button>
          <el-button @click="closeEditor()">Cancel</el-button>
          <el-button v-if="detail?.status==='DRAFT'" type="danger" plain :disabled="!detail?.id" @click="voidSheet(detail)">Void</el-button>
          <el-button v-if="detail?.status==='DRAFT'" @click="focusOrderEntry">Add Sales Order</el-button>
          <el-button v-if="detail?.status==='DRAFT'" type="success" @click="approve">Approve</el-button>
        </div>
      </template>
      <template v-if="detail">
        <div class="legacy-document">
          <div class="document-heading">
            <div class="document-title"><h2>DISPATCH SHEET</h2><div class="status-tags"><el-tag>{{statusText(detail.status)}}</el-tag><el-tag v-if="detail.printedAt" type="primary">Printed {{detail.printCount}} times</el-tag></div></div>
            <div class="document-number">
              <div class="number-cell"><b>Date(D)</b><el-date-picker v-if="detail.status==='DRAFT'" v-model="headerForm.dispatchDate" type="date" value-format="YYYY-MM-DD" :clearable="false" @change="markDraftDirty"/><span v-else>{{detail.dispatchDate}}</span></div>
              <div class="number-cell"><b>Document No.(N)</b><span>{{detail.dispatchNo}}</span></div>
            </div>
          </div>
          <div class="legacy-header-grid">
            <label><span>Route(A)</span><el-select v-if="detail.status==='DRAFT'" v-model="headerForm.routeId" filterable clearable placeholder="Optional" @change="markDraftDirty"><el-option v-for="item in routes" :key="item.id" :label="`${item.code} ${item.name}`" :value="item.id"/></el-select><em v-else>{{detail.routeName||'—'}}</em></label>
            <label><span>Vehicle</span><el-select v-if="detail.status==='DRAFT'" v-model="headerForm.vehicleId" filterable clearable placeholder="Optional" @change="markDraftDirty"><el-option v-for="item in vehicles" :key="item.id" :label="vehicleLabel(item)" :value="item.id"/></el-select><em v-else>{{detail.vehicleCode||'—'}}</em></label>
            <label><span>Driver</span><el-select v-if="detail.status==='DRAFT'" v-model="headerForm.driverId" filterable clearable placeholder="Optional" @change="markDraftDirty"><el-option v-for="item in drivers" :key="item.id" :label="employeeLabel(item)" :value="item.id"/></el-select><em v-else>{{detail.driverName||'—'}}</em></label>
            <label><span>Delivery Person</span><el-select v-if="detail.status==='DRAFT'" v-model="headerForm.deliveryPersonId" filterable clearable placeholder="Optional" @change="markDraftDirty"><el-option v-for="item in employees" :key="item.id" :label="employeeLabel(item)" :value="item.id"/></el-select><em v-else>{{detail.deliveryPersonName||'—'}}</em></label>
          </div>
          <div v-if="detail.status==='DRAFT'" class="order-entry-row"><label><span>Delivery Note</span><el-input ref="orderTailInput" v-model="orderTail" clearable autofocus placeholder="Enter sales order ending digits; leave blank to search all" @keyup.enter="resolveOrderTail"/></label><el-button type="primary" :loading="orderSearching||resolving" @click="resolveOrderTail">Find</el-button><small>A unique ending is added automatically. If multiple orders match, select one below. Only printed sales orders not already assigned to another dispatch sheet are shown.</small></div>
          <div v-if="detail.status==='DRAFT' && availableOrders.length" class="candidate-sheet"><div class="candidate-title">Search Results ({{availableOrders.length}})</div><el-table :data="availableOrders" v-loading="orderSearching" border max-height="220" size="small"><el-table-column prop="orderNo" label="Sales Order No." width="150"/><el-table-column prop="orderDate" label="Date" width="110"/><el-table-column prop="customerCode" label="Customer Code" width="105"/><el-table-column prop="customerName" label="Customer Name" min-width="190"/><el-table-column prop="salespersonName" label="Salesperson" width="95"/><el-table-column prop="totalAmount" label="Amount" width="110"/><el-table-column label="Actions" width="72" fixed="right"><template #default="scope"><el-button link type="primary" :loading="resolving" @click="addResolvedOrder(scope.row.orderNo)">Add</el-button></template></el-table-column></el-table></div>
          <div v-if="detail.status!=='DRAFT'" class="locked-notice">{{detail.status==='APPROVED'?'This dispatch sheet is approved and cannot be edited':'This dispatch sheet is voided'}}</div>
