        </div>
      </template>
    </el-dialog>


    <el-dialog v-model="salesDetailDialog" :title="`Related Document ${salesDetail?.orderNo||''}`" width="960px" append-to-body class="sales-detail-dialog">
      <div v-loading="salesDetailLoading" class="sales-print-host"><SalesOrderPrint v-if="salesDetail" :detail="salesDetail" type="delivery"/></div>
      <template #footer><el-button @click="salesDetailDialog=false">Close</el-button><el-button type="primary" :disabled="!salesDetail" @click="printRelated">Delivery Note Print Preview</el-button></template>
    </el-dialog>

    <el-dialog v-model="dispatchPrintDialog" :title="`Dispatch Sheet Print Preview ${detail?.dispatchNo||''}`" width="1000px" append-to-body class="dispatch-print-dialog">
      <div v-if="detail" class="dispatch-print-area"><div class="delivery-print-title">Dispatch Sheet</div><div class="dispatch-print-meta"><span><strong>Document No.: </strong>{{detail.dispatchNo}}</span><span><strong>Date: </strong>{{detail.dispatchDate}}</span><span><strong>Route: </strong>{{detail.routeName}}</span><span><strong>Vehicle: </strong>{{detail.vehicleCode}}</span><span><strong>Driver: </strong>{{detail.driverName}}</span><span><strong>Delivery Person: </strong>{{detail.deliveryPersonName||'—'}}</span><span><strong>Print Status: </strong>{{detail.printedAt?`Printed ${detail.printCount} times`:'Not Printed'}}</span></div>
        <el-table :data="detail.orders" border><el-table-column prop="sequenceNo" label="No." width="65"/><el-table-column prop="orderNo" label="Sales Order No." width="145"/><el-table-column prop="orderDate" label="Order Date" width="105"/><el-table-column prop="customerCode" label="Customer Code" width="110"/><el-table-column prop="customerName" label="Customer Name" min-width="190"/><el-table-column prop="salespersonName" label="Salesperson" width="90"/><el-table-column prop="settlementMethod" label="Payment Method" width="90"/><el-table-column prop="amount" label="Amount" width="105"/></el-table>
        <div class="delivery-print-total">Total: {{detail.orders.length}} orders, ¥{{totalAmount.toFixed(2)}}</div><div class="delivery-print-footer"><span>Notes: {{detail.remark||'None'}}</span><span>Prepared By: System Administrator</span></div></div>
      <template #footer><el-button @click="dispatchPrintDialog=false">Close</el-button><el-button @click="exportDispatch">Export CSV</el-button><el-button type="primary" @click="printDispatchSheet">Print / Save as PDF</el-button></template>
    </el-dialog>
  </section>
</template>
